<span class="line"><span style="color:#7F848E;font-style:italic;">    /// </span><span style="color:#ABB2BF;font-style:italic;">&lt;</span><span style="color:#E06C75;font-style:italic;">param</span><span style="color:#D19A66;font-style:italic;"> name</span><span style="color:#ABB2BF;font-style:italic;">=</span><span style="color:#98C379;font-style:italic;">&quot;limit&quot;</span><span style="color:#ABB2BF;font-style:italic;">&gt;</span><span style="color:#7F848E;font-style:italic;">窗口内最大请求数</span><span style="color:#ABB2BF;font-style:italic;">&lt;/</span><span style="color:#E06C75;font-style:italic;">param</span><span style="color:#ABB2BF;font-style:italic;">&gt;</span></span>
